    const validTemp = obs.find(x => x.time >= state.params.start && x.temperature !== null), T0 = validTemp ? validTemp.temperature : 40;
    const corrected = obs.map(x => ({x: x.time, y: x.temperature === null ? null : x.pressure - cal.beta * (x.temperature - T0)}));
    const ys = [...obs.map(x => x.pressure), ...corrected.filter(x => x.y !== null).map(x => x.y)], low = Math.min(...ys) - .1, high = Math.max(...ys) + .1;
