'<details class="s17-agent-options s17-agent-sheet"><summary>返回对话</summary><div class="s17-agent-settings-intro"><h3>连接与语音</h3><p>填写 Key，开始和井见对话。</p></div><p id="s17-agent-model-status">本地导览已就绪。</p><div class="s17-speech-controls"><button type="button" id="s17-agent-read">朗读上一条</button><button type="button" id="s17-agent-stop">停止朗读</button></div><p class="s17-agent-data-note">文字对话保存在本机浏览器。Key 只在当前页面内存使用；附件历史仅保留名称。朗读使用浏览器或系统语音。</p></details><div id="s17-agent-pending" class="s17-agent-pending" role="status" hidden><span class="s17-thinking-dot"></span><span>正在思考</span><button id="s17-agent-cancel" type="button">'+icon('stop')+'停止</button></div><div id="s17-agent-toast" class="s17-agent-toast" role="status" hidden></div>';
document.body.append(root);
const $=id=>document.getElementById(id),log=$('s17-agent-log'),store=g.S17History,options=root.querySelector('.s17-agent-options');
let adapter=null,busy=false,controller=null,lastReply='',requestCount=0,successfulCalls=0,ownerIsParent=false,requestEpoch=0,history=[],historyMode='list',liveReply='',liveNode=null;
const caseById=id=>catalog.find(c=>c.id===id);
function pageContext(){const q=new URLSearchParams(location.hash.split('?')[1]??''),parts=location.hash.replace(/^#\/?/,'').split('?')[0].split('/'),scene=g.ATLAS?.index?.byScene?.[parts[1]],current=standalone?caseById(pageInfo.sceneId):null,section=standalone?(document.querySelector('nav[aria-label="案例内容"] [aria-pressed="true"]')?.dataset.tab??location.hash.slice(1)):q.get('tab');return{hash:location.hash||'#/',title:document.querySelector('#view main h1,body>main h1')?.textContent??document.title,sceneId:current?.id??(parts[0]==='scene'?parts[1]:null),tab:({background:'bg',workflow:'flow',lab:'demo'}[section]??section)||'bg',sceneName:current?.name??scene?.name??null,surface:standalone?'standalone':'portal'};}
function updateContext(){const c=pageContext(),section={bg:'专业背景',flow:'案例流程',demo:'可运行示范'}[c.tab];$('s17-agent-context').textContent='正在看 · '+(c.sceneName?c.sceneName+' / '+section:c.title);}
function portalURL(hash){if(standalone&&framed)return new URL('../portal/index.html'+hash,document.baseURI).href;return standalone||pageInfo.portalHref?(pageInfo.portalHref??'../../../../portal/index.html')+hash:hash;}
function destination(action){
if(!action||typeof action!=='object')throw Error('导航参数无效');
const inTeacherFrame=standalone&&framed&&location.href==='about:srcdoc';
if(action.target==='fluorescence_reference')return{label:'真实白光 / UV 对照',href:inTeacherFrame?new URL('../portal/reference/fluorescence.html',document.baseURI).href:pageInfo.referenceHref??'reference/fluorescence.html',newTab:true};
if(action.target==='home')return{label:'网站首页',href:portalURL('#/'),newTab:standalone&&framed};
if(action.target==='chain')return{label:'13阶段作业链',href:portalURL('#/chain'),newTab:standalone&&framed};
if(action.target==='mudlogging')return{label:'录井五个场景',href:portalURL('#/stage/mudlogging'),newTab:standalone&&framed};
const c=caseById(action.target);
if(c){const tab=['bg','flow','demo'].includes(action.tab)?action.tab:'demo',localTab={bg:'background',flow:'workflow',demo:'lab'}[tab],saved=!!g.Cases?.get(c.caseId),directory=c.directory??'cases';
if(standalone&&c.id===pageInfo.sceneId)return{label:{bg:'专业背景',flow:'案例流程',demo:'可运行示范'}[tab]+' · '+c.name,href:'#'+localTab,localTab};
const path=directory+'/'+c.caseId+'/demo/index.html#'+localTab,href=saved?'#/scene/'+c.id+'?case='+c.caseId+'&tab='+tab:inTeacherFrame?new URL('../dist/'+path,document.baseURI).href:(standalone?'../../../':pageInfo.distHref??'../dist/')+path;
return{label:c.name+' · '+({bg:'专业背景',flow:'案例流程',demo:'交互演示'}[tab]),href,newTab:!saved,caseId:c.caseId,sceneId:c.id};}
throw Error('只支持本站已声明的导航目标');}
function richText(container,text){for(const line of String(text).split('\n')){if(!line.trim()){container.append(document.createElement('br'));continue;}const p=document.createElement('p');if(/^\s*[-*]\s+/.test(line))p.className='s17-chat-bullet';const clean=line.replace(/^\s*[-*]\s+/,'');for(const token of clean.split(/(\*\*[^*]+\*\*|`[^`]+`)/g)){const el=token.startsWith('**')&&token.endsWith('**')?document.createElement('strong'):token.startsWith('`')&&token.endsWith('`')?document.createElement('code'):document.createTextNode(token);if(el.nodeType===1)el.textContent=token.startsWith('**')?token.slice(2,-2):token.slice(1,-1);p.append(el);}container.append(p);}}
function toast(text){const node=$('s17-agent-toast');node.textContent=text;node.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.hidden=true,2400);}

function syncComposer(){const input=$('s17-agent-input'),m=g.S17Media?.snapshot();$('s17-agent-send').disabled=busy||m?.processing||m?.recording||(!input.value.trim()&&!m?.files.length);}
function attachmentMenu(value){$('s17-agent-attachment-menu').hidden=!value;$('s17-agent-attach').setAttribute('aria-expanded',String(value));}
function welcome(){const node=document.createElement('p');node.className='s17-agent-welcome';node.textContent='从一个问题开始，我们一起读懂当前案例。';log.replaceChildren(node);}
function actionLinks(container,actions,limit=6){container.replaceChildren();for(const action of actions.slice(0,limit)){try{const d=destination(action),a=document.createElement('a');a.textContent=d.label;a.href=d.href;if(d.localTab)a.dataset.agTab=d.localTab;if(d.newTab){a.target='_blank';a.rel='noopener';}container.append(a);}catch{}}}
function renderMessage(m){log.querySelector('.s17-agent-welcome')?.remove();const wrap=document.createElement('article');wrap.className='s17-agent-message';wrap.dataset.role=m.role;const label=document.createElement('small');label.className='s17-message-origin';label.textContent=m.role==='user'?'你':m.origin||'井见 · 本地导览';const content=document.createElement('div');content.className='s17-message-content';richText(content,m.content);wrap.append(label,content);if(m.actions?.length){const row=document.createElement('div');row.className='s17-agent-actions';actionLinks(row,m.actions);wrap.append(row);}if(m.role==='assistant'){const copy=document.createElement('button');copy.type='button';copy.className='s17-message-copy';copy.innerHTML=icon('copy')+'<span>复制</span>';copy.onclick=async()=>{try{await navigator.clipboard.writeText(m.content);toast('回复已复制');}catch{toast('可选中文字，使用系统复制');}};wrap.append(copy);}log.append(wrap);log.scrollTop=log.scrollHeight;}
function clearLive(){liveNode?.remove();liveNode=null;liveReply='';root.dataset.streaming='false';}
function showLive(delta){liveReply+=delta;root.dataset.streaming='true';if(!liveNode){liveNode=document.createElement('article');liveNode.className='s17-agent-message s17-live-message';const origin=document.createElement('small');origin.className='s17-message-origin';origin.textContent='井见 · 正在回答';const content=document.createElement('div');content.className='s17-message-content';liveNode.append(origin,content);log.append(liveNode);}const follow=log.scrollHeight-log.scrollTop-log.clientHeight<70;liveNode.querySelector('.s17-message-content').textContent=liveReply;if(follow)log.scrollTop=log.scrollHeight;updateBubble();}
function updateBubble(){const m=[...history].reverse().find(m=>m.role==='assistant');lastReply=m?.content??'';$('s17-agent-excerpt').textContent=busy?(liveReply||'正在想一想，稍等一下…'):lastReply||'你好，我是井见。想了解当前案例，还是找一个新的知识点？';actionLinks($('s17-agent-bubble-actions'),busy?[]:m?.actions??[],1);$('s17-agent-full').hidden=!history.length&&!liveReply;$('s17-agent-reply').hidden=root.dataset.open!=='true';$('s17-agent-reply').setAttribute('aria-busy',String(busy));if(busy&&liveReply)$('s17-agent-excerpt').scrollTop=$('s17-agent-excerpt').scrollHeight;}
function renderConversation(){history=store.current().messages;log.replaceChildren();if(!history.length)welcome();else history.forEach(renderMessage);updateBubble();updateContext();}
function storageNotice(){const persistent=store.snapshot().status==='persistent';$('s17-agent-storage').textContent=persistent?'已保存在本机浏览器':'本页无法持久保存，离开后不会保留本次对话';root.dataset.storage=persistent?'persistent':'memory';}
function resetDraft(){g.S17Media?.cancelRecording();g.S17Media?.clear();g.speechSynthesis?.cancel();root.dataset.speaking='false';$('s17-agent-input').value='';$('s17-agent-input').style.height='';syncComposer();}
function renderSessions(){const host=$('s17-agent-sessions');host.replaceChildren();for(const s of store.list()){const row=document.createElement('div');row.className='s17-session-row';row.dataset.sessionId=s.id;const button=document.createElement('button');button.type='button';button.className='s17-session-open';const title=document.createElement('strong'),date=document.createElement('span');title.textContent=s.title;date.textContent=new Date(s.updatedAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})+' · '+s.count+'条消息';button.append(title,date);button.onclick=()=>{stopRequest();resetDraft();store.activate(s.id);renderConversation();showHistory(false);};const remove=document.createElement('button');remove.type='button';remove.className='s17-session-delete';remove.setAttribute('aria-label','删除对话：'+s.title);remove.innerHTML=icon('trash');remove.title='删除这段对话';remove.onclick=()=>{if(store.current().id===s.id){stopRequest();resetDraft();}store.remove(s.id);renderConversation();renderSessions();storageNotice();};row.append(button,remove);host.append(row);}if(!host.children.length){const empty=document.createElement('p');empty.textContent='还没有历史对话。发送一条消息后会自动保存。';host.append(empty);}}
function append(role,text,actions=[],origin='井见 · 本地导览'){const m=store.append({role,content:text,actions,origin,page:pageContext()});history=store.current().messages;renderMessage(m);updateBubble();storageNotice();if(root.dataset.view==='history'&&historyMode==='list')renderSessions();}
const ready=store.ready.then(()=>{renderConversation();storageNotice();});
function guide(text){const t=text.toLowerCase().trim();if(/从哪里|如何开始|怎么开始|五个|全部案例|导览/.test(t))return{text:'可以按“岩屑 → 气测 → 荧光 → 钻时 → 报告”看，也可以直接选一例。每例都有背景、流程和交互演示。首页还收录其他12个阶段的新增案例。已载入的案例进入门户对应页，其余可直接打开独立演示。',actions:[...catalog.filter(c=>/^m[1-5]$/.test(c.id)).map(c=>({target:c.id})),{target:'home'}]};if(/真实.*荧光|真实.*配对|白光.*对照|方解石/.test(t))return{text:'这组真实照片展示同组方解石在可见光、短波UV和长波UV下的外观，用来理解矿物发光与油气解释的区别；不是含油岩屑训练数据。',actions:[{target:'fluorescence_reference'}]};if(/首页|回去|返回主页/.test(t))return{text:'点这里回到网站首页。',actions:[{target:'home'}]};if(/作业链|全部阶段|(?:查看|打开|进入|浏览).{0,4}13(?:个)?阶段|^13(?:个)?阶段$/.test(t))return{text:'点这里查看原门户保留的作业链导航。',actions:[{target:'chain'}]};if(/录井阶段|进入录井/.test(t))return{text:'录井阶段包含五个必做子场景。',actions:[{target:'mudlogging'}]};if(/当前页|这个页面/.test(t)){const p=pageContext(),c=caseById(p.sceneId);return{text:c?c.intro:'当前是“'+p.title+'”。可以从首页选择案例，或通过13阶段导航浏览场景。',actions:c?[{target:c.id,tab:'bg'},{target:c.id,tab:'flow'},{target:c.id,tab:'demo'}]:[{target:'mudlogging'}]};}const c=catalog.find(c=>new RegExp('(?:^|[^a-z0-9])'+c.id+'(?:$|[^a-z0-9])','i').test(t)||c.terms.some(w=>t.includes(w)));if(c&&(!adapter||/打开|带我|进入|跳到|去看|看看/.test(t)||/^(m[1-5]|气测|岩屑|荧光|钻时|报告)$/.test(t))){let tab=/背景|概念/.test(t)?'bg':/流程|步骤/.test(t)?'flow':'demo';return{text:c.intro+'\n可以从这里进入对应内容。',actions:[{target:c.id,tab}]};}if(!adapter&&/模型|api|live2d|数字人|语音/.test(t))return{text:'角色状态：'+(g.S17Live2D?.state??'准备中')+'。本地导航与固定导学可用；在“连接与语音”填写 Key 后即可开放式提问。浏览器朗读可手动开启。',actions:[]};return null;}
const tools=[{name:'navigate_page',description:'提供本站页面导航，仅使用允许的target，不执行JS或任意URL。',parameters:{type:'object',properties:{target:{type:'string',enum:['home','chain','mudlogging',...catalog.map(c=>c.id),'fluorescence_reference']},tab:{type:'string',enum:['bg','flow','demo']}},required:['target']}}];

function setBusy(value){busy=value;g.S17Media?.setBusy(value);$('s17-agent-pending').hidden=!value;$('s17-agent-mode').textContent=value?'正在请求模型':adapter?.name??'本地导览';root.dataset.busy=String(value);updateBubble();syncComposer();}
function stopRequest(){if(!busy)return;const partial=liveReply;requestEpoch++;controller?.abort();controller=null;clearLive();setBusy(false);append('assistant',partial?partial+'\n\n（已停止生成。）':'已停止本次生成。',[],'井见 · 已停止');}
async function ask(text){await ready;const media=g.S17Media;if(busy)return;if(media?.snapshot().processing||media?.snapshot().recording){media.notice('请先结束录音或等待附件准备完成。');return;}const parts=media?.parts()??[];if(!text.trim()&&!parts.length)return;if(parts.length&&!adapter){append('assistant','附件已在本地准备好。在线助手暂未接通，请稍后重试；本地导览仍可使用。',[],'连接状态');return;}
const question=text.trim()||(parts.some(p=>p.type==='input_audio')?'请听取录音并回答其中的问题。':'请解释这张图片中可见的内容。'),names=media?.snapshot().files.map(f=>f.name)??[];append('user',question+(names.length?'\n[本轮附件：'+names.join('、')+'；后续轮次未自动重传]':''));$('s17-agent-input').value='';$('s17-agent-input').style.height='';const local=parts.length?null:guide(question);if(local){append('assistant',local.text,local.actions);syncComposer();return;}if(!adapter){append('assistant','可以先让我介绍当前案例、解释步骤，或者带你定位页面。连接大模型后，我们还可以继续讨论具体问题。',catalog.slice(0,5).map(c=>({target:c.id})));syncComposer();return;}
clearLive();const model=adapter,sessionId=store.current().id,token=++requestEpoch,messages=history.slice(-24).map(m=>({role:m.role,content:m.content}));if(parts.length)messages[messages.length-1].content=[{type:'input_text',text:question},...parts];controller=new AbortController();const requestController=controller,signal=requestController.signal,timeout=setTimeout(()=>requestController.abort(),45000);setBusy(true);
try{requestCount++;const result=await model.reply({messages,context:{page:pageContext(),cases:catalog,scope:'静态教学演示；仅用户本轮明确附上的图片/录音作为多模态输入；历史附件只保留名称。'},tools,signal,onDelta:delta=>{if(token===requestEpoch&&sessionId===store.current().id)showLive(delta);}});if(token!==requestEpoch||sessionId!==store.current().id||model!==adapter)return;if(!result||typeof result.text!=='string'||!result.text.trim())throw Error('模型未返回可显示的文本');successfulCalls++;clearLive();append('assistant',result.text,Array.isArray(result.actions)?result.actions:[],model.name+' · 模型回复');media?.clear();$('s17-agent-badge').textContent='在线';if($('s17-agent-autoread')?.checked&&root.dataset.open==='true')readReply();}
catch(e){if(token===requestEpoch&&sessionId===store.current().id){const partial=liveReply;clearLive();append('assistant',(partial?partial+'\n\n':'')+'本次请求未完成：'+(e.name==='AbortError'?'已取消或超时':e.message)+'。可以重试。',[],'井见 · 连接状态');}}
finally{clearTimeout(timeout);if(token===requestEpoch){controller=null;setBusy(false);}}
}
function clearSheets(){options.open=false;$('s17-agent-history-panel').hidden=true;root.dataset.view='chat';$('s17-agent-settings').setAttribute('aria-pressed','false');}
function open(focus=true){if(ownerIsParent)return;root.dataset.compact='false';root.dataset.open='true';$('s17-agent-panel').hidden=false;$('s17-agent-launcher').setAttribute('aria-expanded','true');$('s17-agent-launcher').setAttribute('aria-label','与井见打招呼');$('s17-agent-compact').setAttribute('aria-pressed','false');updateBubble();updateContext();g.S17Live2D?.greet?.();if(focus)$('s17-agent-input').focus({preventScroll:true});}
function close(){stopRequest();attachmentMenu(false);clearSheets();root.dataset.open='false';$('s17-agent-panel').hidden=true;g.S17Media?.cancelRecording();g.speechSynthesis?.cancel();root.dataset.speaking='false';updateBubble();$('s17-agent-launcher').setAttribute('aria-expanded','false');$('s17-agent-launcher').setAttribute('aria-label','打开井见助手');$('s17-agent-launcher').focus({preventScroll:true});}
async function showHistory(list=true){await ready;open(false);options.open=false;root.dataset.view='history';historyMode=list?'list':'messages';$('s17-agent-settings').setAttribute('aria-pressed','false');$('s17-agent-history-panel').hidden=false;$('s17-agent-sessions').hidden=!list;log.hidden=list;$('s17-agent-context').hidden=list;$('s17-agent-session-back').hidden=list;$('s17-agent-history-title').textContent=list?'历史对话':store.current().title;storageNotice();renderSessions();if(!list)log.scrollTop=log.scrollHeight;$('s17-agent-sheet-close').focus({preventScroll:true});}
function showSettings(value){if(!value){clearSheets();return;}open(false);$('s17-agent-history-panel').hidden=true;root.dataset.view='settings';options.open=true;options.scrollTop=0;$('s17-agent-settings').setAttribute('aria-pressed','true');options.querySelector('summary').focus({preventScroll:true});}
